if(($argv[1]??'')==='worker'){require_once dirname(__DIR__).'/issuers_core_support.php';require_once APPPATH.'services/CompanyClientImports.php';$p=$argv[2]??'';if(!preg_match('/^essential_[a-f0-9]{10}_$/D',$p))exit(2);$input=json_decode(stream_get_contents(STDIN),true,16,JSON_THROW_ON_ERROR);$db=clientImportConnection($p);$GLOBALS['essentialPrefix']=$p;try{$result=(new CompanyClientImports($db,$p))->commit(82,12,$input['batch'],$input['revision'],$input['key']);echo json_encode($result['client_ids'],JSON_THROW_ON_ERROR);}catch(DomainException $e){if($e->getMessage()!=='company_client_import_access_denied')throw $e;echo 'revoked';}exit(0);}
require __DIR__.'/client_imports.php';$observer=clientImportConnection($p);$blocker=(int)$db->query('SELECT CONNECTION_ID() id')->row()->id;
// Retire synthetic quota previews so each new scenario receives one explicitly reviewed batch.
$revisionMethod=new ReflectionMethod(CompanyClientImports::class,'revision');foreach($db->query("SELECT * FROM {$p}company_client_import_batches WHERE issuer_id=82 AND state='preview'")->result_array() as $retired){$retired['issuer_id']=(int)$retired['issuer_id'];$retired['actor_id']=(int)$retired['actor_id'];$retired['row_count']=(int)$retired['row_count'];$retired['expires_at']='2000-01-01 00:00:00';$db->query('UPDATE '.$p.'company_client_import_batches SET expires_at=?,revision=? WHERE batch_id=?',[$retired['expires_at'],$revisionMethod->invoke(null,$retired),$retired['batch_id']]);}
foreach(['retry','grant_revoked','batch_owner_changed'] as $scenario){$batch=$imports->preview(82,12,'json',json_encode([['company'=>'Race '.$scenario.' first'],['company'=>'Race '.$scenario.' second']]),$ik('race-preview-'.$scenario));$preview=$imports->get(82,12,$batch);$before=(int)$db->query('SELECT COUNT(*) n FROM '.$p.'issuers_clients WHERE owner_issuer_id=82')->row()->n;$db->trans_begin();$db->query('SELECT id FROM '.$p.'issuers_lock WHERE id=1 FOR UPDATE');$workers=[];
 try{for($i=0;$i<2;$i++){$pipes=[];$process=proc_open([PHP_BINARY,__FILE__,'worker',$p],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fwrite($pipes[0],json_encode(['batch'=>$batch,'revision'=>$preview['revision'],'key'=>$ik('race-commit-'.$scenario)],JSON_THROW_ON_ERROR));fclose($pipes[0]);$workers[]=[$process,$pipes];}$deadline=microtime(true)+15;do{$waiting=essentialLockWaiters($observer,$blocker);if($waiting>=2)break;usleep(20000);}while(microtime(true)<$deadline);essentialCheck($waiting>=2,'two customer import confirmations observed waiting on the actual InnoDB lock');if($scenario==='grant_revoked')$db->query("DELETE FROM {$p}issuers_resource_permissions WHERE issuer_id=82 AND staff_id=12 AND feature='imports' AND capability='manage'");if($scenario==='batch_owner_changed')$db->query('UPDATE '.$p.'company_client_import_batches SET issuer_id=41 WHERE batch_id=?',[$batch]);$db->trans_commit();$results=[];foreach($workers as [$process,$pipes]){$results[]=stream_get_contents($pipes[1]);$error=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);essentialCheck(proc_close($process)===0&&$error==='','customer import worker completes without private-data diagnostics');}if($scenario==='retry')essentialCheck($results[0]===$results[1]&&str_starts_with($results[0],'[')&&(int)$db->query('SELECT COUNT(*) n FROM '.$p.'issuers_clients WHERE owner_issuer_id=82')->row()->n===$before+2,'concurrent identical batch confirms create two identities exactly once');else essentialCheck($results===['revoked','revoked']&&(int)$db->query('SELECT COUNT(*) n FROM '.$p.'issuers_clients WHERE owner_issuer_id=82')->row()->n===$before,'grant/owner change during wait denies entire batch before any identity effect');
 }finally{if($db->pdo->inTransaction())$db->trans_rollback();if($scenario==='grant_revoked')$db->query("INSERT INTO {$p}issuers_resource_permissions(issuer_id,staff_id,feature,capability) VALUES(82,12,'imports','manage')");}
}
